// Generates the code of every language from specs/.
//
//   bun generator/src/main.ts           write the generated files
//   bun generator/src/main.ts --check   fail when a generated file differs from what it writes
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import * as cs from './emit-cs.ts';
import * as java from './emit-java.ts';
import * as py from './emit-py.ts';
import * as ts from './emit-ts.ts';
import { buildIr, ROOT } from './ir.ts';
import { operationCases } from './cases.ts';

export function generatedFiles(): Record<string, string> {
  const ir = buildIr();
  const tsDir = 'typescript/src/generated';
  const pyDir = 'python/src/medisync/_generated';
  const pyNames = py.pythonNames(ir);
  const javaNames = java.javaNames(ir);
  const dotnetNames = cs.dotnetNames(ir);
  const names = {
    version: ir.version,
    operations: ir.operations.map((o) => ({ api: o.api, operationId: o.operationId, typescript: o.name, python: pyNames[o.name], java: javaNames[o.name], dotnet: dotnetNames[o.name] })),
    helpers: ir.helpers.map((h) => ({ typescript: h.name, python: pyNames[h.name], java: javaNames[h.name], dotnet: dotnetNames[h.name] })),
  };
  return {
    [`${tsDir}/types/platform.ts`]: ts.emitTypes(ir.models.platform, 'specs/openapi.json'),
    [`${tsDir}/types/connect.ts`]: ts.emitTypes(ir.models.connect, 'specs/connect-openapi.json'),
    [`${tsDir}/types/live.ts`]: ts.emitTypes(ir.models.live, 'specs/asyncapi.yaml') + ts.emitLiveUnions(ir),
    [`${tsDir}/operations.ts`]: ts.emitOperations(ir),
    [`${tsDir}/resources.ts`]: ts.emitResources(ir),
    [`${pyDir}/__init__.py`]: '# Generated by generator/src/main.ts. Do not edit; run `bun run generate`.\n',
    [`${pyDir}/platform_types.py`]: py.emitModels(ir.models.platform, 'specs/openapi.json'),
    [`${pyDir}/connect_types.py`]: py.emitModels(ir.models.connect, 'specs/connect-openapi.json'),
    [`${pyDir}/live_types.py`]: py.emitModels(ir.models.live, 'specs/asyncapi.yaml', py.liveUnions(ir)),
    [`${pyDir}/operations.py`]: py.emitOperations(ir),
    [`${pyDir}/resources.py`]: py.emitResources(ir),
    ...java.emitJava(ir),
    ...cs.emitCs(ir),
    'conformance/operations.json': `${JSON.stringify(names, null, 2)}\n`,
    'conformance/cases/operations.generated.json': `${JSON.stringify({ generated: 'generator/src/cases.ts; do not edit', cases: operationCases(ir) }, null, 2)}\n`,
  };
}

if (import.meta.main) {
  const check = process.argv.includes('--check');
  const stale: string[] = [];
  for (const [file, content] of Object.entries(generatedFiles())) {
    const path = join(ROOT, file);
    if (check) {
      let current = '';
      try {
        current = readFileSync(path, 'utf8');
      } catch {}
      if (current !== content) stale.push(relative(ROOT, path));
      continue;
    }
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  }
  if (stale.length) {
    console.error(`Generated files are out of date: ${stale.join(', ')}. Run bun run generate.`);
    process.exit(1);
  }
  console.log(check ? 'Generated files are up to date.' : 'Generated the TypeScript, Python, Java and C# code.');
}
